class Solution {
    unordered_map<int, int> value;

    int dfs(int depth, int pos, int sum) {
        int key = depth * 10 + pos;
        if (!value.count(key)) {
            return 0;
        }
        sum += value[key];
        int left = (depth + 1) * 10 + (2 * pos - 1);
        int right = (depth + 1) * 10 + 2 * pos;
        if (!value.count(left) && !value.count(right)) {
            return sum;
        }
        return dfs(depth + 1, 2 * pos - 1, sum)
             + dfs(depth + 1, 2 * pos, sum);
    }

public:
    int pathSum(vector<int>& nums) {
        value.clear();
        for (int x : nums) {
            value[x / 10] = x % 10;
        }
        return dfs(1, 1, 0);
    }
};
